<?php require_once 'layout.php'; require_admin();
function upload_images($pid){
 if(empty($_FILES['images']['name'][0])) return;
 foreach($_FILES['images']['tmp_name'] as $i=>$tmp){
  if(!is_uploaded_file($tmp)) continue;
  $ext=strtolower(pathinfo($_FILES['images']['name'][$i],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp','gif'])) continue;
  $name='p'.$pid.'_'.time().'_'.$i.'.'.$ext; move_uploaded_file($tmp, UPLOAD_DIR.'/'.$name); db()->prepare('INSERT INTO product_images(product_id,image_path) VALUES(?,?)')->execute([$pid,$name]);
 }}
function replace_product_image($imgId,$file){
 if(empty($file['tmp_name']) || !is_uploaded_file($file['tmp_name'])) return false;
 $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp','gif'])) return false;
 $s=db()->prepare('SELECT image_path FROM product_images WHERE id=?');$s->execute([$imgId]);$old=$s->fetchColumn();
 $name='img'.$imgId.'_'.time().'.'.$ext; move_uploaded_file($file['tmp_name'], UPLOAD_DIR.'/'.$name);
 if($old && $old!='logo.jpg' && file_exists(UPLOAD_DIR.'/'.$old)) @unlink(UPLOAD_DIR.'/'.$old);
 db()->prepare('UPDATE product_images SET image_path=? WHERE id=?')->execute([$name,$imgId]); return true;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['add_cat'])){db()->prepare('INSERT OR IGNORE INTO categories(name) VALUES(?)')->execute([trim($_POST['cat_name'])]);flash('Kategori eklendi.');redirect(BASE_URL.'/admin.php#kategoriler');}
 if(isset($_POST['edit_cat'])){db()->prepare('UPDATE categories SET name=? WHERE id=?')->execute([trim($_POST['cat_name']),(int)$_POST['cat_id']]);flash('Kategori düzenlendi.');redirect(BASE_URL.'/admin.php#kategoriler');}
 if(isset($_POST['delete_cat'])){$cid=(int)$_POST['cat_id'];$cnt=db()->prepare('SELECT COUNT(*) FROM products WHERE category_id=?');$cnt->execute([$cid]); if($cnt->fetchColumn()>0) flash('Bu kategoride ürün var. Önce ürünleri sil veya başka kategoriye taşı.'); else {db()->prepare('DELETE FROM categories WHERE id=?')->execute([$cid]); flash('Kategori silindi.');} redirect(BASE_URL.'/admin.php#kategoriler');}
 if(isset($_POST['replace_existing']) && !empty($_FILES['replace_image']['name'])){ foreach($_FILES['replace_image']['name'] as $id=>$name){ $file=['name'=>$name,'type'=>$_FILES['replace_image']['type'][$id]??'','tmp_name'=>$_FILES['replace_image']['tmp_name'][$id]??'','error'=>$_FILES['replace_image']['error'][$id]??0,'size'=>$_FILES['replace_image']['size'][$id]??0]; replace_product_image((int)$id,$file); } flash('Fotoğraflar güncellendi.'); redirect(BASE_URL.'/admin.php?edit='.(int)($_POST['product_id']??0).'#ekle'); }
 if(isset($_POST['add_product'])||isset($_POST['update_product'])){
  $price=(float)str_replace(',','.',preg_replace('/[^0-9.,]/','',$_POST['price']??'0')); $stock=max(0,(int)$_POST['stock']);
  if(isset($_POST['add_product'])){db()->prepare('INSERT INTO products(category_id,name,description,price,stock) VALUES(?,?,?,?,?)')->execute([(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['description']),$price,$stock]);$pid=db()->lastInsertId();upload_images($pid);flash('Ürün eklendi.');}
  else {$pid=(int)$_POST['product_id'];db()->prepare('UPDATE products SET category_id=?,name=?,description=?,price=?,stock=? WHERE id=?')->execute([(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['description']),$price,$stock,$pid]);upload_images($pid);flash('Ürün düzenlendi.');}
  redirect(BASE_URL.'/admin.php'.(isset($pid)?'?edit='.$pid.'#ekle':''));
 }
}
if(isset($_GET['delprod'])){db()->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_GET['delprod']]);flash('Ürün silindi.');redirect(BASE_URL.'/admin.php');}
if(isset($_GET['delimg'])){ $s=db()->prepare('SELECT image_path FROM product_images WHERE id=?');$s->execute([(int)$_GET['delimg']]);$img=$s->fetchColumn(); if($img&&$img!='logo.jpg'&&file_exists(UPLOAD_DIR.'/'.$img)) unlink(UPLOAD_DIR.'/'.$img); db()->prepare('DELETE FROM product_images WHERE id=?')->execute([(int)$_GET['delimg']]);redirect(BASE_URL.'/admin.php?edit='.(int)($_GET['pid']??0).'#ekle');}
$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$orders=db()->query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll();$messages=db()->query('SELECT * FROM messages ORDER BY id DESC')->fetchAll();page_header('Admin Paneli'); ?>
<h1 class="page-title">Admin Paneli</h1><p class="muted">Kategoriler, ürünler, stoklar, çoklu fotoğraflar ve siparişler buradan yönetilir.</p>
<div class="tabs"><button class="tab active" data-tab="urunler" onclick="showTab('urunler')">Ürünler</button><button class="tab" data-tab="ekle" onclick="showTab('ekle')">Ürün Ekle / Düzenle</button><button class="tab" data-tab="kategoriler" onclick="showTab('kategoriler')">Kategoriler</button><button class="tab" data-tab="siparisler" onclick="showTab('siparisler')">Siparişler</button><button class="tab" data-tab="mesajlar" onclick="showTab('mesajlar')">Mesajlar</button></div>
<section id="urunler" class="admin-section active card spacious"><h2>Ürünler Kategori Kategori</h2><?php foreach($cats as $c): ?><h3 class="pill cat-title"><?=h($c['name'])?></h3><div class="table-wrap"><table class="table"><tr><th>Ürün</th><th>Fiyat</th><th>Stok</th><th>Fotoğraflar</th><th>İşlem</th></tr><?php $ps=db()->prepare('SELECT * FROM products WHERE category_id=? ORDER BY id DESC');$ps->execute([$c['id']]);foreach($ps->fetchAll() as $p): ?><tr><td><b><?=h($p['name'])?></b><p class="muted small"><?=h(mb_strimwidth($p['description'],0,60,'...'))?></p></td><td><?=money_try($p['price'])?></td><td><?=h($p['stock'])?></td><td class="admin-photos"><?php $ims=db()->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY id');$ims->execute([$p['id']]);$n=1;foreach($ims->fetchAll() as $im): ?><span><b><?=$n++?>. Fotoğraf</b><img src="<?=UPLOAD_URL.'/'.h($im['image_path'])?>"><a href="?delimg=<?=$im['id']?>&pid=<?=$p['id']?>" onclick="return confirm('Fotoğraf silinsin mi?')">sil</a></span><?php endforeach; ?></td><td><a class="btn" href="?edit=<?=$p['id']?>#ekle">Düzenle</a><a class="btn danger" onclick="return confirm('Silinsin mi?')" href="?delprod=<?=$p['id']?>">Sil</a></td></tr><?php endforeach; ?></table></div><?php endforeach; ?></section>
<section id="ekle" class="admin-section card spacious"><h2><?= $edit?'Ürünü Düzenle':'Yeni Ürün Ekle' ?></h2><form method="post" enctype="multipart/form-data" class="form nice-form"><input type="hidden" name="product_id" value="<?=h($edit['id']??'')?>"><select name="category_id" required><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=($edit['category_id']??'')==$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach; ?></select><input name="name" placeholder="Ürün adı" value="<?=h($edit['name']??'')?>" required><textarea name="description" placeholder="Açıklama" required><?=h($edit['description']??'')?></textarea><div class="row"><input type="number" name="price" min="0" step="0.01" inputmode="decimal" oninput="priceInput(this)" placeholder="Fiyat - sadece sayı" value="<?=h($edit['price']??'')?>" required><input type="number" name="stock" min="0" step="1" placeholder="Stok" value="<?=h($edit['stock']??'0')?>" required></div><label>Yeni ürün fotoğrafları / çoklu seçilebilir</label><input type="file" name="images[]" multiple accept="image/*"><button class="btn primary" name="<?=$edit?'update_product':'add_product'?>"><?= $edit?'Düzenlemeyi Kaydet':'Ürün Ekle' ?></button><?php if($edit): ?><a class="btn" href="admin.php">Yeni ürün moduna dön</a><?php endif; ?></form>
<?php if($edit): $ims=db()->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY id');$ims->execute([$edit['id']]);$imgs=$ims->fetchAll(); ?>
<div class="existing-photos"><h3>Mevcut Fotoğraflar</h3><p class="muted">Buradan her fotoğrafı tek tek görebilir, silebilir veya başka fotoğrafla değiştirebilirsin.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="product_id" value="<?=$edit['id']?>"><div class="photo-editor-grid"><?php $n=1; foreach($imgs as $im): ?><div class="photo-edit-card"><b><?=$n++?>. Fotoğraf</b><img src="<?=UPLOAD_URL.'/'.h($im['image_path'])?>" onclick="openImage(this.src)"><input type="file" name="replace_image[<?=$im['id']?>]" accept="image/*"><a class="btn danger" href="?delimg=<?=$im['id']?>&pid=<?=$edit['id']?>" onclick="return confirm('Fotoğraf silinsin mi?')">Sil</a></div><?php endforeach; ?></div><button class="btn primary" name="replace_existing">Seçilen Fotoğrafları Değiştir</button></form></div><div id="imgModal" class="modal" onclick="closeImage()"><span class="close">×</span><img id="modalImg"></div><?php endif; ?></section>
<section id="kategoriler" class="admin-section card spacious"><h2>Kategori Yönetimi</h2><form method="post" class="actions"><input class="field" name="cat_name" placeholder="Yeni kategori adı" required><button class="btn primary" name="add_cat">Kategori Ekle</button></form><div class="grid"><?php foreach($cats as $c): ?><form method="post" class="card nice-form"><input type="hidden" name="cat_id" value="<?=$c['id']?>"><label>Kategori adı</label><input name="cat_name" value="<?=h($c['name'])?>" required><div class="actions"><button class="btn" name="edit_cat">Düzenle</button><button class="btn danger" name="delete_cat" onclick="return confirm('Kategori silinsin mi?')">Sil</button></div></form><?php endforeach; ?></div></section>
<section id="siparisler" class="admin-section card spacious"><h2>Siparişler</h2><?php foreach($orders as $o): ?><div class="soft-item"><b>#<?=$o['id']?> · <?=h($o['email'])?> · <?=money_try($o['total'])?></b><?php if(!empty($o['currency'])&&$o['currency']!=='TRY'): ?> <b>/ <?=h($o['currency'])?> <?=number_format((float)$o['converted_total'],2,'.',',')?></b><?php endif; ?><p><?=h($o['fullname'])?> · <?=h($o['phone'])?> · <?=h($o['province'].'/'.$o['district'].'/'.($o['neighborhood']??'').' '.$o['address'])?> · Kart: ****<?=h($o['card_last4'])?></p><?php $it=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$it->execute([$o['id']]);foreach($it->fetchAll() as $x): ?><p>• <?=h($x['product_name'])?> x<?=$x['quantity']?></p><?php endforeach; ?></div><?php endforeach; ?></section>
<section id="mesajlar" class="admin-section card spacious"><h2>Mesajlar</h2><?php foreach($messages as $m): ?><div class="soft-item"><b><?=h($m['name'])?> · <?=h($m['email'])?></b><p><?=h($m['message'])?></p></div><?php endforeach; ?></section>
<?php if($edit): ?><script>document.addEventListener('DOMContentLoaded',()=>showTab('ekle'));</script><?php endif; ?>
<?php page_footer(); ?>
